/* Saraiki Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmed": "most praised — Arabic", "Fatima": "A beloved feminine name.", "Muhammad": "praised — Arabic", "Amina": "trustworthy — Arabic", "Allah Ditta": "given by God — Persian/Arabic", "Ghulam": "servant — Arabic", "Langah": "A historic Saraiki tribal name.", "Khosa": "A great tribal name of the region.", "Leghari": "A great tribal name of Dera Ghazi Khan.", "Mazari": "A great tribal name of the region."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmed';
console.log(lookup(q));

